insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('d4763630-c8c0-4291-a775-1087ea2ecd38', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Course Orientation, Units, Modeling Assumptions, and Problem-Solving Workflow', 'This opening unit frames Statics as the art of replacing real objects with useful mechanical models. Students learn the habits that keep equilibrium problems organized, checkable, and physically meaningful.', 0),
  ('fdf569c2-0757-4a9c-b474-1b6117d225c6', '186edb1c-a07a-4228-a469-5286790f95ad', 'd4763630-c8c0-4291-a775-1087ea2ecd38', 'subtopic'::public.curated_course_node_type, 'What Statics Studies', 'Students learn what it means for particles and rigid bodies to be in equilibrium and why this course is foundational for engineering design.', 0),
  ('9efc6f4b-9f8a-4316-a8bf-9ba0876f44c8', '186edb1c-a07a-4228-a469-5286790f95ad', 'fdf569c2-0757-4a9c-b474-1b6117d225c6', 'concept'::public.curated_course_node_type, 'Statics versus dynamics', null, 0),
  ('5f7ed774-9fb8-478e-982a-375a72994524', '186edb1c-a07a-4228-a469-5286790f95ad', 'fdf569c2-0757-4a9c-b474-1b6117d225c6', 'concept'::public.curated_course_node_type, 'Rigid-body idealization', null, 1),
  ('c596a091-ce1b-418a-952f-263789b59508', '186edb1c-a07a-4228-a469-5286790f95ad', 'fdf569c2-0757-4a9c-b474-1b6117d225c6', 'concept'::public.curated_course_node_type, 'Connections to mechanics of materials, structures, dynamics, and design', null, 2),
  ('8745ec90-f156-4ffb-ba24-bf17cef47fec', '186edb1c-a07a-4228-a469-5286790f95ad', 'd4763630-c8c0-4291-a775-1087ea2ecd38', 'subtopic'::public.curated_course_node_type, 'Units, Dimensions, and Significant Figures', 'Consistent units are part of engineering reasoning, not just formatting. They catch mistakes and preserve physical meaning.', 1),
  ('36679c02-2dc8-4d43-8eec-9f960e05751a', '186edb1c-a07a-4228-a469-5286790f95ad', '8745ec90-f156-4ffb-ba24-bf17cef47fec', 'concept'::public.curated_course_node_type, 'SI and US customary systems', null, 0),
  ('e15ebfe6-f2ef-4b8a-80e0-9394acff90d4', '186edb1c-a07a-4228-a469-5286790f95ad', '8745ec90-f156-4ffb-ba24-bf17cef47fec', 'concept'::public.curated_course_node_type, 'Force, mass, length, time, and moment units', null, 1),
  ('22bd404a-a3e9-4158-8582-8be32a6dd2a3', '186edb1c-a07a-4228-a469-5286790f95ad', '8745ec90-f156-4ffb-ba24-bf17cef47fec', 'concept'::public.curated_course_node_type, 'Dimensional checks and reasonable-result checks', null, 2),
  ('52d5fbb3-ebb7-4749-935a-02e67b1e47a4', '186edb1c-a07a-4228-a469-5286790f95ad', 'd4763630-c8c0-4291-a775-1087ea2ecd38', 'subtopic'::public.curated_course_node_type, 'Modeling and Solution Workflow', 'A repeatable workflow helps students move from a messy word problem to equations that match the physical system.', 2),
  ('c50ee346-7de9-4a55-a15e-3d0ceea59f15', '186edb1c-a07a-4228-a469-5286790f95ad', '52d5fbb3-ebb7-4749-935a-02e67b1e47a4', 'concept'::public.curated_course_node_type, 'Read, sketch, define system, draw FBD, choose axes', null, 0),
  ('68f19224-a54f-4966-a786-4ead4428de9e', '186edb1c-a07a-4228-a469-5286790f95ad', '52d5fbb3-ebb7-4749-935a-02e67b1e47a4', 'concept'::public.curated_course_node_type, 'Write equilibrium equations before substituting numbers', null, 1),
  ('eb6d619f-962b-4e31-8e33-601601964d86', '186edb1c-a07a-4228-a469-5286790f95ad', '52d5fbb3-ebb7-4749-935a-02e67b1e47a4', 'concept'::public.curated_course_node_type, 'Check signs, units, constraints, and limiting cases', null, 2),
  ('a7fd8c54-528a-4050-ab4d-87d37ed8dd56', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Force Vectors and Coordinate Systems', 'Statics begins with representing forces as vectors. This unit gives students the mathematical language for magnitude, direction, components, and resultants in two and three dimensions.', 1),
  ('c5e4ab60-ce77-42a8-8daa-52be23dd1808', '186edb1c-a07a-4228-a469-5286790f95ad', 'a7fd8c54-528a-4050-ab4d-87d37ed8dd56', 'subtopic'::public.curated_course_node_type, 'Vector Representation of Forces', 'Students learn to describe a force by magnitude, direction, line of action, and point of application.', 0),
  ('58daa52e-af32-49f2-9541-7ee845e3d2bc', '186edb1c-a07a-4228-a469-5286790f95ad', 'c5e4ab60-ce77-42a8-8daa-52be23dd1808', 'concept'::public.curated_course_node_type, 'Scalars versus vectors', null, 0),
  ('9c516a3b-76b0-43c4-9b32-900e942247c2', '186edb1c-a07a-4228-a469-5286790f95ad', 'c5e4ab60-ce77-42a8-8daa-52be23dd1808', 'concept'::public.curated_course_node_type, 'Graphical and analytical representations', null, 1),
  ('7db4dd93-2f38-4aee-9efb-dfffdd5bae53', '186edb1c-a07a-4228-a469-5286790f95ad', 'c5e4ab60-ce77-42a8-8daa-52be23dd1808', 'concept'::public.curated_course_node_type, 'Line of action and transmissibility for rigid bodies', null, 2),
  ('2ea17110-19dc-4a4f-9508-73011824ae74', '186edb1c-a07a-4228-a469-5286790f95ad', 'a7fd8c54-528a-4050-ab4d-87d37ed8dd56', 'subtopic'::public.curated_course_node_type, 'Components and Unit Vectors', 'Component form turns geometry into algebra so multiple forces can be added and balanced.', 1),
  ('abd0e243-ee45-4b83-92c4-282152f5d914', '186edb1c-a07a-4228-a469-5286790f95ad', '2ea17110-19dc-4a4f-9508-73011824ae74', 'concept'::public.curated_course_node_type, 'Rectangular components in 2D and 3D', null, 0),
  ('2e0e57cf-8045-4596-ac10-51993132bdc3', '186edb1c-a07a-4228-a469-5286790f95ad', '2ea17110-19dc-4a4f-9508-73011824ae74', 'concept'::public.curated_course_node_type, 'Direction cosines', null, 1),
  ('c17f0fa8-2655-4c6f-be69-7ec483bb2955', '186edb1c-a07a-4228-a469-5286790f95ad', '2ea17110-19dc-4a4f-9508-73011824ae74', 'concept'::public.curated_course_node_type, 'Unit vector notation along lines and cables', null, 2),
  ('41bd1f3c-badd-4cfd-969f-727650173cca', '186edb1c-a07a-4228-a469-5286790f95ad', 'a7fd8c54-528a-4050-ab4d-87d37ed8dd56', 'subtopic'::public.curated_course_node_type, 'Resultants of Concurrent Forces', 'Resultants simplify multiple forces into one equivalent vector for analysis.', 2),
  ('519136a7-20b8-4a89-a829-1625fd7161c4', '186edb1c-a07a-4228-a469-5286790f95ad', '41bd1f3c-badd-4cfd-969f-727650173cca', 'concept'::public.curated_course_node_type, 'Vector addition and subtraction', null, 0),
  ('378e2b59-6b86-4fa6-8159-0472d881e8e6', '186edb1c-a07a-4228-a469-5286790f95ad', '41bd1f3c-badd-4cfd-969f-727650173cca', 'concept'::public.curated_course_node_type, 'Parallelogram and polygon methods', null, 1),
  ('36bc8518-55ff-43fc-897a-b4e8a8b016b0', '186edb1c-a07a-4228-a469-5286790f95ad', '41bd1f3c-badd-4cfd-969f-727650173cca', 'concept'::public.curated_course_node_type, 'Component summation and angle recovery', null, 2),
  ('a4dca1e0-fbae-46e7-a631-a1b70949ed1f', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Particles in Equilibrium', 'Particle equilibrium strips mechanics down to its essentials: forces meeting at a point must balance. This unit builds confidence with force balances before students analyze full rigid bodies.', 2),
  ('957503f6-4dfd-404d-80c4-ccd781c8f11d', '186edb1c-a07a-4228-a469-5286790f95ad', 'a4dca1e0-fbae-46e7-a631-a1b70949ed1f', 'subtopic'::public.curated_course_node_type, 'Particle Free-Body Diagrams', 'Students practice isolating a point-like object and showing every external force acting on it.', 0),
  ('acff94b5-19cb-4840-8af5-e370789c081c', '186edb1c-a07a-4228-a469-5286790f95ad', '957503f6-4dfd-404d-80c4-ccd781c8f11d', 'concept'::public.curated_course_node_type, 'Cables, springs, weights, and contact forces', null, 0),
  ('e306332a-2aa5-452d-a95c-de9222f75d67', '186edb1c-a07a-4228-a469-5286790f95ad', '957503f6-4dfd-404d-80c4-ccd781c8f11d', 'concept'::public.curated_course_node_type, 'Known and unknown force labels', null, 1),
  ('ede8b11e-89ef-4bab-9be3-c9a41638fc1c', '186edb1c-a07a-4228-a469-5286790f95ad', '957503f6-4dfd-404d-80c4-ccd781c8f11d', 'concept'::public.curated_course_node_type, 'Tension direction and two-force members', null, 2),
  ('6c6b1481-1de7-4d95-a252-13d99e55732f', '186edb1c-a07a-4228-a469-5286790f95ad', 'a4dca1e0-fbae-46e7-a631-a1b70949ed1f', 'subtopic'::public.curated_course_node_type, 'Two-Dimensional Particle Equilibrium', 'This subtopic turns diagrams into force equations in x and y directions.', 1),
  ('7343dcab-c94a-4e75-a773-62e0347045d2', '186edb1c-a07a-4228-a469-5286790f95ad', '6c6b1481-1de7-4d95-a252-13d99e55732f', 'concept'::public.curated_course_node_type, 'Sum of forces in x and y', null, 0),
  ('acad5f3f-c0a3-4e06-972e-a26ea6fe9659', '186edb1c-a07a-4228-a469-5286790f95ad', '6c6b1481-1de7-4d95-a252-13d99e55732f', 'concept'::public.curated_course_node_type, 'Solving two-unknown systems', null, 1),
  ('ad0cc2e2-76fe-4fe1-886c-c4f1784383f5', '186edb1c-a07a-4228-a469-5286790f95ad', '6c6b1481-1de7-4d95-a252-13d99e55732f', 'concept'::public.curated_course_node_type, 'Inclined planes and pulley-supported particles', null, 2),
  ('e331deac-8603-4827-bc12-bd94c8829e48', '186edb1c-a07a-4228-a469-5286790f95ad', 'a4dca1e0-fbae-46e7-a631-a1b70949ed1f', 'subtopic'::public.curated_course_node_type, 'Three-Dimensional Particle Equilibrium', '3D particle problems prepare students for cables, spatial supports, and real engineering geometry.', 2),
  ('7aa2f004-e1cf-47a9-8f87-c615454e7165', '186edb1c-a07a-4228-a469-5286790f95ad', 'e331deac-8603-4827-bc12-bd94c8829e48', 'concept'::public.curated_course_node_type, 'Unit vectors along 3D cables', null, 0),
  ('1e9735a1-2fd9-4271-982b-5e5646ef916d', '186edb1c-a07a-4228-a469-5286790f95ad', 'e331deac-8603-4827-bc12-bd94c8829e48', 'concept'::public.curated_course_node_type, 'Sum of forces in x, y, and z', null, 1),
  ('a10120b1-8b03-42b6-87e7-f01dfd256652', '186edb1c-a07a-4228-a469-5286790f95ad', 'e331deac-8603-4827-bc12-bd94c8829e48', 'concept'::public.curated_course_node_type, 'Solving multi-cable support systems', null, 2),
  ('a043e7f9-0076-4b8d-8553-4d99cbb7a97a', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Moments, Couples, and Moment Resultants', 'Moments explain rotational tendency and are central to analyzing beams, supports, machines, and structures. This unit teaches students to compute and interpret moments in scalar and vector form.', 3),
  ('1cc75dcb-fda1-4cf2-9c5a-7f2be5065c2a', '186edb1c-a07a-4228-a469-5286790f95ad', 'a043e7f9-0076-4b8d-8553-4d99cbb7a97a', 'subtopic'::public.curated_course_node_type, 'Moment of a Force in 2D', 'Students learn how a force creates rotation about a point and how distance from the line of action matters.', 0),
  ('9456e0b9-953c-478b-a241-2090921f1f77', '186edb1c-a07a-4228-a469-5286790f95ad', '1cc75dcb-fda1-4cf2-9c5a-7f2be5065c2a', 'concept'::public.curated_course_node_type, 'Moment arm and perpendicular distance', null, 0),
  ('ecd9425a-e10a-424e-bee2-bcb37a41fba3', '186edb1c-a07a-4228-a469-5286790f95ad', '1cc75dcb-fda1-4cf2-9c5a-7f2be5065c2a', 'concept'::public.curated_course_node_type, 'Clockwise and counterclockwise sign conventions', null, 1),
  ('aa78197b-d159-444b-a878-1d5a09194a6b', '186edb1c-a07a-4228-a469-5286790f95ad', '1cc75dcb-fda1-4cf2-9c5a-7f2be5065c2a', 'concept'::public.curated_course_node_type, 'Varignon''s theorem', null, 2),
  ('d4b8880d-68a4-46ef-ae5c-c3c7398fce30', '186edb1c-a07a-4228-a469-5286790f95ad', 'a043e7f9-0076-4b8d-8553-4d99cbb7a97a', 'subtopic'::public.curated_course_node_type, 'Vector Moments in 3D', 'Cross products make moments usable in spatial problems with arbitrary geometry.', 1),
  ('4df16cb9-0eaa-4072-bb08-9cbaf623632f', '186edb1c-a07a-4228-a469-5286790f95ad', 'd4b8880d-68a4-46ef-ae5c-c3c7398fce30', 'concept'::public.curated_course_node_type, 'Position vector and force vector', null, 0),
  ('18b9ba1d-1d9a-4979-9cd2-8c0cee860742', '186edb1c-a07a-4228-a469-5286790f95ad', 'd4b8880d-68a4-46ef-ae5c-c3c7398fce30', 'concept'::public.curated_course_node_type, 'Right-hand rule', null, 1),
  ('b7a8bb2e-f7b4-4169-a62d-9062f578778c', '186edb1c-a07a-4228-a469-5286790f95ad', 'd4b8880d-68a4-46ef-ae5c-c3c7398fce30', 'concept'::public.curated_course_node_type, 'Moment about a point and moment about an axis', null, 2),
  ('33b7ce9e-32b7-4ff9-af27-2e2cff8e4f03', '186edb1c-a07a-4228-a469-5286790f95ad', 'a043e7f9-0076-4b8d-8553-4d99cbb7a97a', 'subtopic'::public.curated_course_node_type, 'Couples and Moment Resultants', 'Couples are pure rotational effects that can be moved on a rigid body without changing external equilibrium.', 2),
  ('901af7b3-5630-4571-b63c-f031b0df7771', '186edb1c-a07a-4228-a469-5286790f95ad', '33b7ce9e-32b7-4ff9-af27-2e2cff8e4f03', 'concept'::public.curated_course_node_type, 'Couple moment definition', null, 0),
  ('3155fb56-c93c-4fc0-9697-a252b61cb301', '186edb1c-a07a-4228-a469-5286790f95ad', '33b7ce9e-32b7-4ff9-af27-2e2cff8e4f03', 'concept'::public.curated_course_node_type, 'Equivalent couples', null, 1),
  ('6b2fd792-ac22-4f46-b14b-80226f281f44', '186edb1c-a07a-4228-a469-5286790f95ad', '33b7ce9e-32b7-4ff9-af27-2e2cff8e4f03', 'concept'::public.curated_course_node_type, 'Combining force and couple systems', null, 2),
  ('3507474b-01a5-4cbe-80f3-2cca2f677774', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Rigid-Body Free-Body Diagrams', 'Free-body diagrams are the core professional habit of Statics. This unit teaches students to isolate bodies, represent supports correctly, and convert physical constraints into forces and moments.', 4),
  ('4122de60-8bba-42e4-99b3-b63cf575371e', '186edb1c-a07a-4228-a469-5286790f95ad', '3507474b-01a5-4cbe-80f3-2cca2f677774', 'subtopic'::public.curated_course_node_type, 'External Forces and System Boundaries', 'Students learn that the choice of system determines which forces are external and which interactions disappear.', 0),
  ('7bc8f0b4-c7a9-4475-b6b1-0281875ed05a', '186edb1c-a07a-4228-a469-5286790f95ad', '4122de60-8bba-42e4-99b3-b63cf575371e', 'concept'::public.curated_course_node_type, 'Body isolation and boundary selection', null, 0),
  ('94291943-f9e8-46fb-b5ab-febacc7e6163', '186edb1c-a07a-4228-a469-5286790f95ad', '4122de60-8bba-42e4-99b3-b63cf575371e', 'concept'::public.curated_course_node_type, 'Applied loads, weights, contact forces, and reactions', null, 1),
  ('f0aed277-b456-49b3-b0b6-c6d77fb7f279', '186edb1c-a07a-4228-a469-5286790f95ad', '4122de60-8bba-42e4-99b3-b63cf575371e', 'concept'::public.curated_course_node_type, 'Internal versus external forces', null, 2),
  ('06848567-9ee8-473d-a1c8-837c0843c416', '186edb1c-a07a-4228-a469-5286790f95ad', '3507474b-01a5-4cbe-80f3-2cca2f677774', 'subtopic'::public.curated_course_node_type, 'Support and Connection Models', 'Students learn the standard idealizations used for pins, rollers, fixed supports, smooth contacts, links, and cables.', 1),
  ('cbe7c54f-29fd-4946-9d35-a513bc884c0b', '186edb1c-a07a-4228-a469-5286790f95ad', '06848567-9ee8-473d-a1c8-837c0843c416', 'concept'::public.curated_course_node_type, 'Roller, pin, fixed, collar, ball-and-socket, and journal bearings', null, 0),
  ('6d8c3abd-1765-45f2-9fbc-f5089038f8f3', '186edb1c-a07a-4228-a469-5286790f95ad', '06848567-9ee8-473d-a1c8-837c0843c416', 'concept'::public.curated_course_node_type, 'Two-force and three-force members', null, 1),
  ('fcfb8f50-bd28-4ce9-a95c-afd98543d7b8', '186edb1c-a07a-4228-a469-5286790f95ad', '06848567-9ee8-473d-a1c8-837c0843c416', 'concept'::public.curated_course_node_type, 'Distributed contacts and simplified reactions', null, 2),
  ('b4791ecf-3906-4869-91d9-86df473d5a1a', '186edb1c-a07a-4228-a469-5286790f95ad', '3507474b-01a5-4cbe-80f3-2cca2f677774', 'subtopic'::public.curated_course_node_type, 'Diagram Quality and Error Checking', 'A good FBD is a reasoning tool. Students learn how to spot missing forces, double-counting, and impossible assumptions.', 2),
  ('b2add256-cc3d-4918-8e7f-4f0880efe7d1', '186edb1c-a07a-4228-a469-5286790f95ad', 'b4791ecf-3906-4869-91d9-86df473d5a1a', 'concept'::public.curated_course_node_type, 'Coordinate axes and sign conventions', null, 0),
  ('e8fdf621-fbfd-4708-8070-249d99255280', '186edb1c-a07a-4228-a469-5286790f95ad', 'b4791ecf-3906-4869-91d9-86df473d5a1a', 'concept'::public.curated_course_node_type, 'Unknown labels before equations', null, 1),
  ('4fe46629-c24a-4075-a478-7467bd575e70', '186edb1c-a07a-4228-a469-5286790f95ad', 'b4791ecf-3906-4869-91d9-86df473d5a1a', 'concept'::public.curated_course_node_type, 'Action-reaction pairs and support count checks', null, 2),
  ('890417b4-4abb-4721-874e-6ac18ebbe401', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Rigid-Body Equilibrium in Two Dimensions', 'This unit applies force and moment balance to planar bodies. Students analyze beams, brackets, ladders, plates, and simple structures using three independent equilibrium equations.', 5),
  ('04e5868e-b91b-4340-818e-ed47079990c9', '186edb1c-a07a-4228-a469-5286790f95ad', '890417b4-4abb-4721-874e-6ac18ebbe401', 'subtopic'::public.curated_course_node_type, 'Planar Equilibrium Equations', 'Students learn how translational and rotational equilibrium constrain a body in 2D.', 0),
  ('8e2c6f99-dfd7-4448-b99e-3d0ae587114a', '186edb1c-a07a-4228-a469-5286790f95ad', '04e5868e-b91b-4340-818e-ed47079990c9', 'concept'::public.curated_course_node_type, 'Sum of forces in x and y', null, 0),
  ('981e3640-abf8-446b-b586-6f4a30a62050', '186edb1c-a07a-4228-a469-5286790f95ad', '04e5868e-b91b-4340-818e-ed47079990c9', 'concept'::public.curated_course_node_type, 'Sum of moments about a chosen point', null, 1),
  ('ed37a459-78cf-49a7-b670-ee79e203998e', '186edb1c-a07a-4228-a469-5286790f95ad', '04e5868e-b91b-4340-818e-ed47079990c9', 'concept'::public.curated_course_node_type, 'Alternative moment equation sets', null, 2),
  ('e0bf120d-e670-43c7-9088-d0d270a8dd3e', '186edb1c-a07a-4228-a469-5286790f95ad', '890417b4-4abb-4721-874e-6ac18ebbe401', 'subtopic'::public.curated_course_node_type, 'Support Reactions for Planar Bodies', 'Support reactions connect FBDs to actual load transfer through pins, rollers, fixed supports, and contacts.', 1),
  ('4b0a4dfe-f71a-4f40-9da1-1fd50567d28f', '186edb1c-a07a-4228-a469-5286790f95ad', 'e0bf120d-e670-43c7-9088-d0d270a8dd3e', 'concept'::public.curated_course_node_type, 'Simply supported, cantilevered, and overhanging bodies', null, 0),
  ('06d20f7c-d353-42fd-bb4d-6620e8cc676d', '186edb1c-a07a-4228-a469-5286790f95ad', 'e0bf120d-e670-43c7-9088-d0d270a8dd3e', 'concept'::public.curated_course_node_type, 'Solving for reaction forces and moments', null, 1),
  ('93e5937a-7d6d-4168-9fb0-e398b89f5e03', '186edb1c-a07a-4228-a469-5286790f95ad', 'e0bf120d-e670-43c7-9088-d0d270a8dd3e', 'concept'::public.curated_course_node_type, 'Choosing moment centers to reduce algebra', null, 2),
  ('17df8fd4-f2ad-47aa-9f49-984157aa64f0', '186edb1c-a07a-4228-a469-5286790f95ad', '890417b4-4abb-4721-874e-6ac18ebbe401', 'subtopic'::public.curated_course_node_type, 'Determinacy and Stability', 'Students learn when equilibrium equations are enough and when a model is unstable or statically indeterminate.', 2),
  ('75f2a08b-6f80-40bb-b3eb-6fd3fe89c90e', '186edb1c-a07a-4228-a469-5286790f95ad', '17df8fd4-f2ad-47aa-9f49-984157aa64f0', 'concept'::public.curated_course_node_type, 'Unknown count versus equation count', null, 0),
  ('c0b017f2-89af-4341-926f-18e23c191eb3', '186edb1c-a07a-4228-a469-5286790f95ad', '17df8fd4-f2ad-47aa-9f49-984157aa64f0', 'concept'::public.curated_course_node_type, 'Improper constraints and mechanisms', null, 1),
  ('fd4d080b-7903-4cab-b1a2-faf5deb4ca06', '186edb1c-a07a-4228-a469-5286790f95ad', '17df8fd4-f2ad-47aa-9f49-984157aa64f0', 'concept'::public.curated_course_node_type, 'Physical interpretation of negative reactions', null, 2),
  ('c1e0f9db-85cc-4626-ada0-7ce4829f40d2', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Rigid-Body Equilibrium in Three Dimensions', 'Three-dimensional equilibrium prepares students for real supports, spatial frames, machine components, and aerospace structures where forces and moments act in all directions.', 6),
  ('c718b76d-2132-4cd5-886b-8eea606f74c5', '186edb1c-a07a-4228-a469-5286790f95ad', 'c1e0f9db-85cc-4626-ada0-7ce4829f40d2', 'subtopic'::public.curated_course_node_type, 'Spatial Free-Body Diagrams', 'Students learn to represent 3D supports and applied loads clearly enough to write six equilibrium equations.', 0);
