values
  ('88fec7a7-9c23-4891-b1b0-03344078a441', '186edb1c-a07a-4228-a469-5286790f95ad', 'c718b76d-2132-4cd5-886b-8eea606f74c5', 'concept'::public.curated_course_node_type, '3D coordinate axes and position vectors', null, 0),
