  ('00738576-5fc6-4703-8be1-8248f25246ca', '186edb1c-a07a-4228-a469-5286790f95ad', 'c718b76d-2132-4cd5-886b-8eea606f74c5', 'concept'::public.curated_course_node_type, 'Vector labels for forces and moments', null, 2),
  ('0c802928-a7e3-4bd5-a33b-0d4645db270c', '186edb1c-a07a-4228-a469-5286790f95ad', 'c1e0f9db-85cc-4626-ada0-7ce4829f40d2', 'subtopic'::public.curated_course_node_type, 'Six Equilibrium Equations', 'A rigid body in 3D requires balancing forces and moments about three axes.', 1),
  ('562268fd-edc7-47be-a2b5-9d472fe8450a', '186edb1c-a07a-4228-a469-5286790f95ad', '0c802928-a7e3-4bd5-a33b-0d4645db270c', 'concept'::public.curated_course_node_type, 'Sum of forces in x, y, and z', null, 0),
  ('8ed2bf05-80d3-40d6-817e-95cdeb60b40d', '186edb1c-a07a-4228-a469-5286790f95ad', '0c802928-a7e3-4bd5-a33b-0d4645db270c', 'concept'::public.curated_course_node_type, 'Sum of moments about x, y, and z', null, 1),
  ('b5686f84-62a6-4eb3-b08a-f16aa2258dbf', '186edb1c-a07a-4228-a469-5286790f95ad', '0c802928-a7e3-4bd5-a33b-0d4645db270c', 'concept'::public.curated_course_node_type, 'Matrix-style organization of unknowns', null, 2),
  ('4d78b603-ca57-4ac1-a0a0-ef65d679d44c', '186edb1c-a07a-4228-a469-5286790f95ad', 'c1e0f9db-85cc-4626-ada0-7ce4829f40d2', 'subtopic'::public.curated_course_node_type, '3D Engineering Applications', 'Students practice spatial reasoning in settings that resemble brackets, shafts, cranes, and aircraft components.', 2),
  ('83ffa701-9ff3-4a59-b657-9a1465e6ff62', '186edb1c-a07a-4228-a469-5286790f95ad', '4d78b603-ca57-4ac1-a0a0-ef65d679d44c', 'concept'::public.curated_course_node_type, 'Cables and guyed structures', null, 0),
  ('4a74b196-5060-4668-867e-fb5ae960d337', '186edb1c-a07a-4228-a469-5286790f95ad', '4d78b603-ca57-4ac1-a0a0-ef65d679d44c', 'concept'::public.curated_course_node_type, 'Bearings and shaft reactions', null, 1),
  ('5badfbb9-5d94-42ff-9172-059e294edba0', '186edb1c-a07a-4228-a469-5286790f95ad', '4d78b603-ca57-4ac1-a0a0-ef65d679d44c', 'concept'::public.curated_course_node_type, 'Moment about a specified axis', null, 2),
  ('5f0d0455-c2e8-480a-80ae-efe854e2d8f5', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Equivalent Force Systems and Distributed Loads', 'Engineers often replace complicated load patterns with simpler equivalent forces and moments. This unit teaches how to preserve external effects while simplifying analysis.', 7),
  ('a89fcb46-33a6-4b22-928d-6663d64e6cc8', '186edb1c-a07a-4228-a469-5286790f95ad', '5f0d0455-c2e8-480a-80ae-efe854e2d8f5', 'subtopic'::public.curated_course_node_type, 'Equivalent Force-Couple Systems', 'Students learn to move forces to convenient points by adding the correct couple moment.', 0),
  ('a720b310-a97e-460b-88fe-fd758ae5eb61', '186edb1c-a07a-4228-a469-5286790f95ad', 'a89fcb46-33a6-4b22-928d-6663d64e6cc8', 'concept'::public.curated_course_node_type, 'Force translation on rigid bodies', null, 0),
  ('fc04b090-e26d-41ec-bbca-b6ded9fb4d8c', '186edb1c-a07a-4228-a469-5286790f95ad', 'a89fcb46-33a6-4b22-928d-6663d64e6cc8', 'concept'::public.curated_course_node_type, 'Resultant force and resultant moment', null, 1),
  ('66acc242-5cd0-4b72-9a9e-4d06bf4d2222', '186edb1c-a07a-4228-a469-5286790f95ad', 'a89fcb46-33a6-4b22-928d-6663d64e6cc8', 'concept'::public.curated_course_node_type, 'Reduction of a general force system', null, 2),
  ('d203b34f-9bdc-4809-9a28-4137958c475f', '186edb1c-a07a-4228-a469-5286790f95ad', '5f0d0455-c2e8-480a-80ae-efe854e2d8f5', 'subtopic'::public.curated_course_node_type, 'Distributed Loads on Beams and Surfaces', 'Distributed loads model weight, pressure, wind, and contact loads more realistically than point forces.', 1),
  ('701319cd-1163-4fb8-a755-4fb19fd2b5c4', '186edb1c-a07a-4228-a469-5286790f95ad', 'd203b34f-9bdc-4809-9a28-4137958c475f', 'concept'::public.curated_course_node_type, 'Uniform, triangular, trapezoidal, and function-defined loads', null, 0),
  ('4a0da22f-f080-471c-8df8-1876e81bf17f', '186edb1c-a07a-4228-a469-5286790f95ad', 'd203b34f-9bdc-4809-9a28-4137958c475f', 'concept'::public.curated_course_node_type, 'Area under load diagram as resultant magnitude', null, 1),
  ('ed498c1c-09cf-432a-bffd-ad647b59dc3c', '186edb1c-a07a-4228-a469-5286790f95ad', 'd203b34f-9bdc-4809-9a28-4137958c475f', 'concept'::public.curated_course_node_type, 'Centroid of load area as resultant location', null, 2),
  ('cf1aa5a4-e010-47e1-af48-7625851de6bf', '186edb1c-a07a-4228-a469-5286790f95ad', '5f0d0455-c2e8-480a-80ae-efe854e2d8f5', 'subtopic'::public.curated_course_node_type, 'Load Paths and Structural Interpretation', 'Students connect mathematical resultants to how loads travel through members and supports.', 2),
  ('698bceac-6f24-4689-86a4-481892073795', '186edb1c-a07a-4228-a469-5286790f95ad', 'cf1aa5a4-e010-47e1-af48-7625851de6bf', 'concept'::public.curated_course_node_type, 'Gravity, wind, and applied load paths', null, 0),
  ('755fd4e8-4f85-4b7b-b0a6-cf4f7f3f516f', '186edb1c-a07a-4228-a469-5286790f95ad', 'cf1aa5a4-e010-47e1-af48-7625851de6bf', 'concept'::public.curated_course_node_type, 'Tributary area intuition', null, 1),
  ('99618375-d9ef-4f47-bd73-dd5c8165a8e5', '186edb1c-a07a-4228-a469-5286790f95ad', 'cf1aa5a4-e010-47e1-af48-7625851de6bf', 'concept'::public.curated_course_node_type, 'When a simplification is reasonable or risky', null, 2),
  ('dc810ece-a46e-43f9-a5bb-c9d9de9798f9', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Trusses: Method of Joints and Method of Sections', 'Trusses introduce structural systems made of connected two-force members. Students learn how equilibrium reveals member tension, compression, and zero-force behavior.', 8),
  ('8d777eb3-74ac-4e93-81d7-9d99310b0c1e', '186edb1c-a07a-4228-a469-5286790f95ad', 'dc810ece-a46e-43f9-a5bb-c9d9de9798f9', 'subtopic'::public.curated_course_node_type, 'Truss Assumptions and Classification', 'Students learn the idealizations that make truss analysis possible and when those idealizations apply.', 0),
  ('fa569f3f-6115-4301-8a51-bd939876f6d1', '186edb1c-a07a-4228-a469-5286790f95ad', '8d777eb3-74ac-4e93-81d7-9d99310b0c1e', 'concept'::public.curated_course_node_type, 'Pin-connected straight members', null, 0),
  ('5c259a90-6ef8-49fd-8988-76a3c0015d8c', '186edb1c-a07a-4228-a469-5286790f95ad', '8d777eb3-74ac-4e93-81d7-9d99310b0c1e', 'concept'::public.curated_course_node_type, 'Loads applied at joints', null, 1),
  ('58511c80-41fd-43d6-9439-e71608915194', '186edb1c-a07a-4228-a469-5286790f95ad', '8d777eb3-74ac-4e93-81d7-9d99310b0c1e', 'concept'::public.curated_course_node_type, 'Simple, compound, and complex trusses', null, 2),
  ('1df990d6-e508-40ee-81cb-3ae62ab89083', '186edb1c-a07a-4228-a469-5286790f95ad', 'dc810ece-a46e-43f9-a5bb-c9d9de9798f9', 'subtopic'::public.curated_course_node_type, 'Method of Joints', 'Joint equilibrium solves member forces by treating each joint as a particle.', 1),
  ('182b1bab-471d-4c14-b204-e2836d057dcd', '186edb1c-a07a-4228-a469-5286790f95ad', '1df990d6-e508-40ee-81cb-3ae62ab89083', 'concept'::public.curated_course_node_type, 'Joint FBDs', null, 0),
  ('6853167b-49e1-417e-908e-0a35da13dccd', '186edb1c-a07a-4228-a469-5286790f95ad', '1df990d6-e508-40ee-81cb-3ae62ab89083', 'concept'::public.curated_course_node_type, 'Tension/compression sign conventions', null, 1),
  ('7b50173a-15c6-4514-8391-85d7ebce986e', '186edb1c-a07a-4228-a469-5286790f95ad', '1df990d6-e508-40ee-81cb-3ae62ab89083', 'concept'::public.curated_course_node_type, 'Zero-force members', null, 2),
  ('602a4894-25e7-4970-941f-60c9b33f7030', '186edb1c-a07a-4228-a469-5286790f95ad', 'dc810ece-a46e-43f9-a5bb-c9d9de9798f9', 'subtopic'::public.curated_course_node_type, 'Method of Sections', 'Sections let students solve selected member forces efficiently without analyzing every joint.', 2),
  ('b60ee1e5-e95e-4f36-8ac8-bbcca9bff611', '186edb1c-a07a-4228-a469-5286790f95ad', '602a4894-25e7-4970-941f-60c9b33f7030', 'concept'::public.curated_course_node_type, 'Strategic cutting through up to three unknown members', null, 0),
  ('b68d78e3-b850-4f11-a087-38a5ef2394ed', '186edb1c-a07a-4228-a469-5286790f95ad', '602a4894-25e7-4970-941f-60c9b33f7030', 'concept'::public.curated_course_node_type, 'Section FBDs and moment choices', null, 1),
  ('6662f76c-91d7-4134-9a6b-9d74e9b5a1b8', '186edb1c-a07a-4228-a469-5286790f95ad', '602a4894-25e7-4970-941f-60c9b33f7030', 'concept'::public.curated_course_node_type, 'Comparison with method of joints', null, 2),
  ('079507fe-d769-4c2f-aafd-a5a4ea0f2fc5', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Frames and Machines', 'Frames and machines contain multi-force members, so they require careful body isolation and interaction forces. This unit deepens students'' FBD discipline.', 9),
  ('a7f3c84d-4386-46e0-a4dc-59f97a2ca086', '186edb1c-a07a-4228-a469-5286790f95ad', '079507fe-d769-4c2f-aafd-a5a4ea0f2fc5', 'subtopic'::public.curated_course_node_type, 'Multi-Force Member Analysis', 'Students distinguish frames and machines from trusses and learn why members must often be isolated individually.', 0),
  ('9fefe71d-53d6-4207-82a0-dbc11cf0e69d', '186edb1c-a07a-4228-a469-5286790f95ad', 'a7f3c84d-4386-46e0-a4dc-59f97a2ca086', 'concept'::public.curated_course_node_type, 'Two-force versus multi-force members', null, 0),
  ('7fadc8f3-3280-458c-b06e-aee63e199697', '186edb1c-a07a-4228-a469-5286790f95ad', 'a7f3c84d-4386-46e0-a4dc-59f97a2ca086', 'concept'::public.curated_course_node_type, 'Pin interactions between connected bodies', null, 1),
  ('e64dfc38-ade7-4c28-871b-0a7e350a170a', '186edb1c-a07a-4228-a469-5286790f95ad', 'a7f3c84d-4386-46e0-a4dc-59f97a2ca086', 'concept'::public.curated_course_node_type, 'Whole-system FBD followed by member FBDs', null, 2),
  ('f4c29610-9830-4e0a-a56b-480689a2cc17', '186edb1c-a07a-4228-a469-5286790f95ad', '079507fe-d769-4c2f-aafd-a5a4ea0f2fc5', 'subtopic'::public.curated_course_node_type, 'Frames', 'Frame analysis focuses on stationary load-supporting assemblies such as brackets and structural linkages.', 1),
  ('c71e845c-5770-41ee-847b-3c7c182f98a0', '186edb1c-a07a-4228-a469-5286790f95ad', 'f4c29610-9830-4e0a-a56b-480689a2cc17', 'concept'::public.curated_course_node_type, 'Support reactions', null, 0),
  ('97e3c8e2-2838-4ab7-a265-10e5b1327c34', '186edb1c-a07a-4228-a469-5286790f95ad', 'f4c29610-9830-4e0a-a56b-480689a2cc17', 'concept'::public.curated_course_node_type, 'Member interaction forces', null, 1),
  ('e6146477-d3db-4d5c-bd11-a60bb9b943d8', '186edb1c-a07a-4228-a469-5286790f95ad', 'f4c29610-9830-4e0a-a56b-480689a2cc17', 'concept'::public.curated_course_node_type, 'Load transfer through connected members', null, 2),
  ('0defcdd1-c2fa-45e5-bef0-21358081c489', '186edb1c-a07a-4228-a469-5286790f95ad', '079507fe-d769-4c2f-aafd-a5a4ea0f2fc5', 'subtopic'::public.curated_course_node_type, 'Machines', 'Machine analysis focuses on assemblies designed to transmit or transform force.', 2),
  ('ae47ac52-6e16-49b7-b4e1-972d4de8e880', '186edb1c-a07a-4228-a469-5286790f95ad', '0defcdd1-c2fa-45e5-bef0-21358081c489', 'concept'::public.curated_course_node_type, 'Mechanical advantage', null, 0),
  ('6c5e896f-a7d9-4d5e-b93e-55eaca4c8b0b', '186edb1c-a07a-4228-a469-5286790f95ad', '0defcdd1-c2fa-45e5-bef0-21358081c489', 'concept'::public.curated_course_node_type, 'Grippers, presses, levers, and linkages', null, 1),
  ('a1460eed-5499-44e8-b58b-6a6e6ccb27c2', '186edb1c-a07a-4228-a469-5286790f95ad', '0defcdd1-c2fa-45e5-bef0-21358081c489', 'concept'::public.curated_course_node_type, 'Input-output force relationships', null, 2),
  ('f8f3caf0-ca1a-4a47-9e52-1bc6a140f624', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Internal Forces, Shear, and Bending Moment Diagrams', 'Internal force diagrams are the bridge from Statics to mechanics of materials. Students learn to reveal axial force, shear, and bending moment inside beams and members.', 10),
  ('1abd178c-0efc-4179-b977-97b8c2537ac0', '186edb1c-a07a-4228-a469-5286790f95ad', 'f8f3caf0-ca1a-4a47-9e52-1bc6a140f624', 'subtopic'::public.curated_course_node_type, 'Internal Force Resultants', 'Students learn what is exposed when a member is cut and why internal forces matter for design.', 0),
  ('4117dc42-f600-448b-ac4a-d4f0873e165d', '186edb1c-a07a-4228-a469-5286790f95ad', '1abd178c-0efc-4179-b977-97b8c2537ac0', 'concept'::public.curated_course_node_type, 'Axial force, shear force, bending moment, and torsion', null, 0),
  ('8f0f4998-3993-48c9-847a-a88fa53871dd', '186edb1c-a07a-4228-a469-5286790f95ad', '1abd178c-0efc-4179-b977-97b8c2537ac0', 'concept'::public.curated_course_node_type, 'Section cuts and sign conventions', null, 1),
  ('ce0b4739-ae56-4a38-af09-a9f70673e3e8', '186edb1c-a07a-4228-a469-5286790f95ad', '1abd178c-0efc-4179-b977-97b8c2537ac0', 'concept'::public.curated_course_node_type, 'Internal versus external equilibrium', null, 2),
  ('aafe3ea6-1851-4916-a56d-05f622353168', '186edb1c-a07a-4228-a469-5286790f95ad', 'f8f3caf0-ca1a-4a47-9e52-1bc6a140f624', 'subtopic'::public.curated_course_node_type, 'Shear and Moment Diagrams', 'Diagrams show how internal shear and bending moment vary along a beam.', 1),
  ('59423b7a-0798-4635-a95e-fe8c6188ab02', '186edb1c-a07a-4228-a469-5286790f95ad', 'aafe3ea6-1851-4916-a56d-05f622353168', 'concept'::public.curated_course_node_type, 'Point loads, distributed loads, and applied couples', null, 0),
  ('62977b7e-8006-4a17-b063-2886d9f3d316', '186edb1c-a07a-4228-a469-5286790f95ad', 'aafe3ea6-1851-4916-a56d-05f622353168', 'concept'::public.curated_course_node_type, 'Piecewise functions and diagram construction', null, 1),
  ('4fafad10-6640-406a-9b27-e3c1cb2c03f4', '186edb1c-a07a-4228-a469-5286790f95ad', 'aafe3ea6-1851-4916-a56d-05f622353168', 'concept'::public.curated_course_node_type, 'Relationships among load, shear, and moment', null, 2),
  ('055de235-de14-4a2f-8a50-d15e5b1a71af', '186edb1c-a07a-4228-a469-5286790f95ad', 'f8f3caf0-ca1a-4a47-9e52-1bc6a140f624', 'subtopic'::public.curated_course_node_type, 'Engineering Interpretation', 'Students learn to connect diagram features to likely stress, deflection, and failure concerns in later courses.', 2),
  ('72b38949-1783-4ab0-bc31-cc9153420515', '186edb1c-a07a-4228-a469-5286790f95ad', '055de235-de14-4a2f-8a50-d15e5b1a71af', 'concept'::public.curated_course_node_type, 'Maximum shear and maximum moment locations', null, 0),
  ('7ad0ac41-26dc-4413-9886-817d2b97026a', '186edb1c-a07a-4228-a469-5286790f95ad', '055de235-de14-4a2f-8a50-d15e5b1a71af', 'concept'::public.curated_course_node_type, 'Simply supported and cantilever beams', null, 1),
  ('302f84da-abea-40dd-b50e-bb76a14f64a5', '186edb1c-a07a-4228-a469-5286790f95ad', '055de235-de14-4a2f-8a50-d15e5b1a71af', 'concept'::public.curated_course_node_type, 'Preparation for bending stress and beam design', null, 2),
  ('531d5269-162c-4028-8251-a90066b93633', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Friction and Contact Mechanics', 'Friction makes equilibrium problems more realistic and more conditional. Students learn how contact forces depend on normal force, impending motion, and surface behavior.', 11),
  ('d9ecb8b2-ed26-4ea6-8ee8-8dad503479e5', '186edb1c-a07a-4228-a469-5286790f95ad', '531d5269-162c-4028-8251-a90066b93633', 'subtopic'::public.curated_course_node_type, 'Dry Friction Fundamentals', 'Students learn how static and kinetic friction limit or resist motion.', 0),
  ('f721a3bd-585b-4b10-9a26-2297de921d37', '186edb1c-a07a-4228-a469-5286790f95ad', 'd9ecb8b2-ed26-4ea6-8ee8-8dad503479e5', 'concept'::public.curated_course_node_type, 'Coefficient of static and kinetic friction', null, 0),
  ('00822058-1fe5-47dc-a464-8559d20cc110', '186edb1c-a07a-4228-a469-5286790f95ad', 'd9ecb8b2-ed26-4ea6-8ee8-8dad503479e5', 'concept'::public.curated_course_node_type, 'Impending motion', null, 1),
  ('1e1f6f8b-95cb-4841-bda2-8aa54dce1165', '186edb1c-a07a-4228-a469-5286790f95ad', 'd9ecb8b2-ed26-4ea6-8ee8-8dad503479e5', 'concept'::public.curated_course_node_type, 'Friction force direction and limiting friction', null, 2),
  ('20d0f2ab-0e5e-4d7d-a09d-4f108e1d9fbd', '186edb1c-a07a-4228-a469-5286790f95ad', '531d5269-162c-4028-8251-a90066b93633', 'subtopic'::public.curated_course_node_type, 'Friction Applications', 'Students apply friction models to wedges, ladders, belts, screws, and brakes.', 1),
  ('320f9626-7506-4994-8e0d-63a6432c6714', '186edb1c-a07a-4228-a469-5286790f95ad', '20d0f2ab-0e5e-4d7d-a09d-4f108e1d9fbd', 'concept'::public.curated_course_node_type, 'Inclined planes and wedges', null, 0),
  ('c0e598a4-14ca-4e47-8eaa-c4e5671a619f', '186edb1c-a07a-4228-a469-5286790f95ad', '20d0f2ab-0e5e-4d7d-a09d-4f108e1d9fbd', 'concept'::public.curated_course_node_type, 'Ladders and tipping/sliding checks', null, 1),
  ('ee8194f1-8731-42f4-975a-e26c5003f638', '186edb1c-a07a-4228-a469-5286790f95ad', '20d0f2ab-0e5e-4d7d-a09d-4f108e1d9fbd', 'concept'::public.curated_course_node_type, 'Belt friction and screw friction overview', null, 2),
  ('aff3a3c5-989b-4c02-99ed-737ff84280f1', '186edb1c-a07a-4228-a469-5286790f95ad', '531d5269-162c-4028-8251-a90066b93633', 'subtopic'::public.curated_course_node_type, 'Contact and Stability Checks', 'Friction problems often require checking whether the assumed contact state is physically possible.', 2),
  ('029cf4a1-a97f-4f38-b2d8-1f132699be46', '186edb1c-a07a-4228-a469-5286790f95ad', 'aff3a3c5-989b-4c02-99ed-737ff84280f1', 'concept'::public.curated_course_node_type, 'Normal force positivity', null, 0),
  ('1de28f5d-839b-44de-a8ad-d2210f9258cc', '186edb1c-a07a-4228-a469-5286790f95ad', 'aff3a3c5-989b-4c02-99ed-737ff84280f1', 'concept'::public.curated_course_node_type, 'Sliding versus tipping', null, 1),
  ('aa1aabb1-4626-41fb-9860-6bbca23e2a8d', '186edb1c-a07a-4228-a469-5286790f95ad', 'aff3a3c5-989b-4c02-99ed-737ff84280f1', 'concept'::public.curated_course_node_type, 'Multiple-contact systems and assumption checks', null, 2),
  ('1f3d42bc-92ca-4a2f-b56e-518ed97ababd', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Centroids, Centers of Gravity, and Moments of Inertia', 'This unit teaches geometric properties that reduce distributed quantities and prepare students for beam bending, torsion, and structural design.', 12),
  ('ff3de960-e69b-468b-a1f5-d6e5dd82488f', '186edb1c-a07a-4228-a469-5286790f95ad', '1f3d42bc-92ca-4a2f-b56e-518ed97ababd', 'subtopic'::public.curated_course_node_type, 'Centroids and Centers of Gravity', 'Students learn to locate representative points for areas, volumes, and weights.', 0),
  ('9c840e65-c00f-4773-aebe-1bc2cdadc250', '186edb1c-a07a-4228-a469-5286790f95ad', 'ff3de960-e69b-468b-a1f5-d6e5dd82488f', 'concept'::public.curated_course_node_type, 'Centroid of lines, areas, and composite shapes', null, 0),
  ('bab6f8a5-6511-4920-b9b7-823ddf987adc', '186edb1c-a07a-4228-a469-5286790f95ad', 'ff3de960-e69b-468b-a1f5-d6e5dd82488f', 'concept'::public.curated_course_node_type, 'Center of gravity and center of mass', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('c995eb81-45d0-401c-8a7f-19dc53c56f34', '186edb1c-a07a-4228-a469-5286790f95ad', 'ff3de960-e69b-468b-a1f5-d6e5dd82488f', 'concept'::public.curated_course_node_type, 'Symmetry and tabular methods', null, 2),
  ('8d999cc5-9080-4713-93cf-9611b6aaf790', '186edb1c-a07a-4228-a469-5286790f95ad', '1f3d42bc-92ca-4a2f-b56e-518ed97ababd', 'subtopic'::public.curated_course_node_type, 'Area Moments of Inertia', 'Area moments of inertia describe how area is distributed relative to an axis and become essential in bending analysis.', 1),
  ('ba078e00-85da-447b-8016-f65900b8e921', '186edb1c-a07a-4228-a469-5286790f95ad', '8d999cc5-9080-4713-93cf-9611b6aaf790', 'concept'::public.curated_course_node_type, 'Second moment of area', null, 0),
