  ('8568db7a-d8e2-44e7-ae03-ecd223956ed7', '186edb1c-a07a-4228-a469-5286790f95ad', '8d999cc5-9080-4713-93cf-9611b6aaf790', 'concept'::public.curated_course_node_type, 'Parallel-axis theorem', null, 2),
  ('8995ef87-10e0-484b-a20e-46991a84dfef', '186edb1c-a07a-4228-a469-5286790f95ad', '1f3d42bc-92ca-4a2f-b56e-518ed97ababd', 'subtopic'::public.curated_course_node_type, 'Mass Moments and Radius of Gyration', 'Students preview properties that matter in dynamics and rotating bodies.', 2),
  ('bad9d858-7ca4-46b7-bdc7-2bd5d4a8a42a', '186edb1c-a07a-4228-a469-5286790f95ad', '8995ef87-10e0-484b-a20e-46991a84dfef', 'concept'::public.curated_course_node_type, 'Mass moment of inertia concepts', null, 0),
  ('2e2190e6-1c90-464f-96d1-e577f2059928', '186edb1c-a07a-4228-a469-5286790f95ad', '8995ef87-10e0-484b-a20e-46991a84dfef', 'concept'::public.curated_course_node_type, 'Radius of gyration', null, 1),
  ('74d67966-5b84-45ad-bd56-424a8489bf19', '186edb1c-a07a-4228-a469-5286790f95ad', '8995ef87-10e0-484b-a20e-46991a84dfef', 'concept'::public.curated_course_node_type, 'Polar moment and product of inertia overview', null, 2),
  ('b914a295-78ff-4793-bb68-ca990d1397b5', '186edb1c-a07a-4228-a469-5286790f95ad', null, 'topic'::public.curated_course_node_type, 'Cables, Virtual Work, and Integrated Statics Applications', 'The final unit consolidates statics reasoning through flexible members, energy-based equilibrium ideas, and cumulative engineering applications.', 13),
  ('8dbbf269-27e2-4064-97aa-3196357018fa', '186edb1c-a07a-4228-a469-5286790f95ad', 'b914a295-78ff-4793-bb68-ca990d1397b5', 'subtopic'::public.curated_course_node_type, 'Cable Systems', 'Students learn how flexible members carry tension and form shapes under concentrated or distributed loads.', 0),
  ('20464352-e751-4896-a42d-e48663564be3', '186edb1c-a07a-4228-a469-5286790f95ad', '8dbbf269-27e2-4064-97aa-3196357018fa', 'concept'::public.curated_course_node_type, 'Cable assumptions and tension', null, 0),
  ('4516bd08-4985-41bd-bb89-b9e27d9c66c6', '186edb1c-a07a-4228-a469-5286790f95ad', '8dbbf269-27e2-4064-97aa-3196357018fa', 'concept'::public.curated_course_node_type, 'Cables with concentrated loads', null, 1),
  ('6dc6f5c8-434b-4931-8f47-11f3eef6a880', '186edb1c-a07a-4228-a469-5286790f95ad', '8dbbf269-27e2-4064-97aa-3196357018fa', 'concept'::public.curated_course_node_type, 'Parabolic cable under uniform load overview', null, 2),
  ('eb72d42a-93d0-4e2a-858b-50d9cda56bd8', '186edb1c-a07a-4228-a469-5286790f95ad', 'b914a295-78ff-4793-bb68-ca990d1397b5', 'subtopic'::public.curated_course_node_type, 'Virtual Work', 'Virtual work offers an alternate equilibrium method that is powerful for machines, mechanisms, and systems with constraints.', 1),
  ('22ac6ca7-47a4-42b7-8c8b-1ddedaf7fe44', '186edb1c-a07a-4228-a469-5286790f95ad', 'eb72d42a-93d0-4e2a-858b-50d9cda56bd8', 'concept'::public.curated_course_node_type, 'Principle of virtual work', null, 0),
  ('9f58c813-8e22-43dc-aed5-e36bace2d8f2', '186edb1c-a07a-4228-a469-5286790f95ad', 'eb72d42a-93d0-4e2a-858b-50d9cda56bd8', 'concept'::public.curated_course_node_type, 'Compatible virtual displacements', null, 1),
  ('fe570e03-7694-4f60-b934-497f111e8afc', '186edb1c-a07a-4228-a469-5286790f95ad', 'eb72d42a-93d0-4e2a-858b-50d9cda56bd8', 'concept'::public.curated_course_node_type, 'Applications to pulleys, linkages, and equilibrium positions', null, 2),
  ('45ab434b-9d60-4168-8dd4-4574e5ad0185', '186edb1c-a07a-4228-a469-5286790f95ad', 'b914a295-78ff-4793-bb68-ca990d1397b5', 'subtopic'::public.curated_course_node_type, 'Integrated Design-Style Problems', 'Students bring the course together by modeling, solving, and checking realistic engineering systems.', 2),
  ('91a28c73-0ac4-41a6-b0f5-ff3c2b9875ba', '186edb1c-a07a-4228-a469-5286790f95ad', '45ab434b-9d60-4168-8dd4-4574e5ad0185', 'concept'::public.curated_course_node_type, 'Combined FBD, equilibrium, friction, and internal-force problems', null, 0),
  ('e18157aa-f7ea-4bd8-8c97-72d1ba2961f4', '186edb1c-a07a-4228-a469-5286790f95ad', '45ab434b-9d60-4168-8dd4-4574e5ad0185', 'concept'::public.curated_course_node_type, 'Load path explanation and result validation', null, 1),
  ('0e0ba410-0ca1-427e-a63a-33718ef1cd59', '186edb1c-a07a-4228-a469-5286790f95ad', '45ab434b-9d60-4168-8dd4-4574e5ad0185', 'concept'::public.curated_course_node_type, 'Communication of assumptions, diagrams, equations, and conclusions', null, 2);
insert into public.curated_course_resources (course_id, kind, title, link_or_site, description, sort_order)
values
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'textbook'::public.curated_course_resource_kind, 'Engineering Mechanics: Statics (Hibbeler)', 'Pearson', 'Standard statics text for force systems, equilibrium, trusses, frames, friction, and virtual work.', 0),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'textbook'::public.curated_course_resource_kind, 'Vector Mechanics for Engineers: Statics', 'McGraw Hill', 'Beer, Johnston, Mazurek, and Cornwell. Strong vector mechanics approach with many engineering examples.', 1),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'textbook'::public.curated_course_resource_kind, 'Engineering Mechanics: Statics (Meriam and Kraige)', 'Wiley', 'Classic rigorous treatment of statics and problem solving.', 2),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'textbook'::public.curated_course_resource_kind, 'Statics and Mechanics of Materials', 'Pearson', 'Integrated bridge from statics into stress, strain, beams, and mechanics of materials.', 3),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'textbook'::public.curated_course_resource_kind, 'Engineering Statics: Open and Interactive', 'https://engineeringstatics.org', 'Free interactive statics text with examples, diagrams, and practice problems.', 4),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'textbook'::public.curated_course_resource_kind, 'Statics and Strength of Materials for Architecture and Building Construction', 'Pearson', 'Onouye and Kane. Useful structural-design context for load paths and equilibrium.', 5),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'website'::public.curated_course_resource_kind, 'Engineering LibreTexts: Statics', 'https://eng.libretexts.org/', 'Open engineering mechanics material with worked explanations and conceptual support.', 6),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'website'::public.curated_course_resource_kind, 'MIT OCW Mechanics and Materials I', 'https://ocw.mit.edu/courses/2-001-mechanics-materials-i-fall-2006/', 'University course material connecting equilibrium and mechanics foundations.', 7),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'website'::public.curated_course_resource_kind, 'Mechanics Map', 'https://mechanicsmap.psu.edu/', 'Visual open mechanics reference for statics, dynamics, and mechanics of materials.', 8),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'website'::public.curated_course_resource_kind, 'eFunda Engineering Fundamentals', 'https://www.efunda.com/', 'Formula and concept reference for mechanics review.', 9),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'website'::public.curated_course_resource_kind, 'ASCE Structural Engineering Institute', 'https://www.asce.org/communities/institutes-and-technical-groups/structural-engineering-institute', 'Professional structural context for equilibrium, load paths, and structural behavior.', 10),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'youtube'::public.curated_course_resource_kind, 'Jeff Hanson', 'https://www.youtube.com/@1234jhanson', 'Excellent statics walkthroughs with many solved problems.', 11),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'youtube'::public.curated_course_resource_kind, 'StructureFree', 'https://www.youtube.com/@StructureFree', 'Engineering mechanics lessons for FBDs, trusses, beams, stress, and strain.', 12),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'youtube'::public.curated_course_resource_kind, 'The Efficient Engineer', 'https://www.youtube.com/@TheEfficientEngineer', 'Clear visual explanations of mechanics, structural behavior, and engineering analysis.', 13),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'youtube'::public.curated_course_resource_kind, 'CPPMechEngTutorials', 'https://www.youtube.com/@CPPMechEngTutorials', 'Worked examples across statics, dynamics, thermodynamics, and engineering mechanics.', 14),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'youtube'::public.curated_course_resource_kind, 'MIT OpenCourseWare', 'https://www.youtube.com/@mitocw', 'University lecture support for mechanics and structures foundations.', 15),
  ('186edb1c-a07a-4228-a469-5286790f95ad', 'youtube'::public.curated_course_resource_kind, 'Practical Engineering', 'https://www.youtube.com/@PracticalEngineeringChannel', 'Applied structural and civil engineering context that makes load paths tangible.', 16);
